namespace Atm;

public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
{
    private const int DailyLimit = 200;
    private const int FeeThreshold = 100;
    private const int WithdrawalFee = 5;
    private const int MaxNotesPerPass = 4;
    private const int CassetteCapacity = 5;

    private readonly IMoneyDispenser _dispenser = dispenser ?? throw new ArgumentNullException(nameof(dispenser));

    public AtmResult Execute(AccountState account, Operation operation) => operation switch
    {
        Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
        Operation.Deposit deposit => Deposit(account, deposit.Notes),
        null => throw new ArgumentNullException(nameof(operation)),
        _ => throw new ArgumentException($"Opération inconnue : {operation.GetType().Name}.", nameof(operation)),
    };

    private AtmResult Withdraw(AccountState account, int amount)
    {
        if (amount <= 0 || amount % 10 != 0)
        {
            return Refuse(AtmStatus.InvalidAmount, account);
        }

        if (account.WithdrawnToday + amount > DailyLimit)
        {
            return Refuse(AtmStatus.DailyLimitExceeded, account);
        }

        var fee = amount > FeeThreshold ? WithdrawalFee : 0;
        if (amount + fee > account.Balance)
        {
            return Refuse(AtmStatus.InsufficientFunds, account);
        }

        if (FewestNotes(amount, Available()) is not { } combination)
        {
            return Refuse(AtmStatus.CannotDispense, account);
        }

        var dispensed = NoteCounts.None;
        foreach (var pass in Passes(combination))
        {
            if (!_dispenser.Dispense(pass))
            {
                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
            }

            dispensed += pass;
        }

        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);

        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    }

    private AtmResult Deposit(AccountState account, NoteCounts notes)
    {
        if (notes.Total <= 0)
        {
            return Refuse(AtmStatus.InvalidAmount, account);
        }

        if (_dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
        {
            return Refuse(AtmStatus.CassetteJammed, account);
        }

        var after = _dispenser.Stock + notes;
        if (after.Fifties > CassetteCapacity || after.Twenties > CassetteCapacity || after.Tens > CassetteCapacity)
        {
            return Refuse(AtmStatus.CassetteFull, account);
        }

        if (!_dispenser.Load(notes))
        {
            return Refuse(AtmStatus.DispenserFault, account);
        }

        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, account with { Balance = account.Balance + notes.Value });
    }

    /// <summary>Le stock utilisable : la cassette bloquée compte pour zéro.</summary>
    private NoteCounts Available()
    {
        var stock = _dispenser.Stock;

        return _dispenser.Jammed switch
        {
            Denomination.Fifty => stock with { Fifties = 0 },
            Denomination.Twenty => stock with { Twenties = 0 },
            Denomination.Ten => stock with { Tens = 0 },
            _ => stock,
        };
    }

    /// <summary>La combinaison qui fait exactement <paramref name="amount"/> avec le moins de billets, ou <c>null</c>.</summary>
    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
    {
        NoteCounts? best = null;
        for (var fifties = 0; fifties <= available.Fifties && fifties * 50 <= amount; fifties++)
        {
            for (var twenties = 0; twenties <= available.Twenties && fifties * 50 + twenties * 20 <= amount; twenties++)
            {
                var rest = amount - fifties * 50 - twenties * 20;
                if (rest % 10 != 0 || rest / 10 > available.Tens)
                {
                    continue;
                }

                var candidate = new NoteCounts(fifties, twenties, rest / 10);
                if (best is not { } current || candidate.Total < current.Total)
                {
                    best = candidate;
                }
            }
        }

        return best;
    }

    /// <summary>Découpe la combinaison en passages d'au plus quatre billets.</summary>
    private static IEnumerable<NoteCounts> Passes(NoteCounts combination)
    {
        var remaining = combination;
        while (remaining.Total > 0)
        {
            var room = MaxNotesPerPass;
            var fifties = Math.Min(remaining.Fifties, room);
            room -= fifties;
            var twenties = Math.Min(remaining.Twenties, room);
            room -= twenties;
            var tens = Math.Min(remaining.Tens, room);

            var pass = new NoteCounts(fifties, twenties, tens);
            remaining -= pass;

            yield return pass;
        }
    }

    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
        new(status, NoteCounts.None, 0, account);
}
namespace Atm;

public enum Denomination { Fifty = 50, Twenty = 20, Ten = 10 }

public enum AtmStatus
{
    Ok,
    InvalidAmount,
    DailyLimitExceeded,
    InsufficientFunds,
    CannotDispense,
    CassetteJammed,
    CassetteFull,
    DispenserFault,
}

public readonly record struct NoteCounts(int Fifties, int Twenties, int Tens)
{
    public static NoteCounts None => default;
    public int Total => Fifties + Twenties + Tens;
    public int Value => Fifties * 50 + Twenties * 20 + Tens * 10;

    public int Of(Denomination denomination) => denomination switch
    {
        Denomination.Fifty => Fifties,
        Denomination.Twenty => Twenties,
        _ => Tens,
    };

    public static NoteCounts operator +(NoteCounts a, NoteCounts b) =>
        new(a.Fifties + b.Fifties, a.Twenties + b.Twenties, a.Tens + b.Tens);

    public static NoteCounts operator -(NoteCounts a, NoteCounts b) =>
        new(a.Fifties - b.Fifties, a.Twenties - b.Twenties, a.Tens - b.Tens);
}

public readonly record struct AccountState(int Balance, int WithdrawnToday);

public abstract record Operation
{
    public sealed record Withdraw(int Amount) : Operation;

    public sealed record Deposit(NoteCounts Notes) : Operation;
}

public readonly record struct AtmResult(AtmStatus Status, NoteCounts Notes, int Fee, AccountState Account);

public interface IMoneyDispenser
{
    NoteCounts Stock { get; }

    Denomination? Jammed { get; }

    bool Dispense(NoteCounts notes);

    bool Load(NoteCounts notes);
}

public interface ICashMachine
{
    AtmResult Execute(AccountState account, Operation operation);
}
namespace Atm;

/// <summary>Le vrai module de billets, déterministe.</summary>
public sealed class MoneyDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    public const int MaxNotesPerPass = 4;
    public const int CassetteCapacity = 5;

    public NoteCounts Stock { get; private set; } = stock;

    public Denomination? Jammed { get; } = jammed;

    public bool Dispense(NoteCounts notes)
    {
        var enough = notes.Fifties <= Stock.Fifties && notes.Twenties <= Stock.Twenties && notes.Tens <= Stock.Tens;
        if (!IsValid(notes) || notes.Total > MaxNotesPerPass || !enough)
        {
            return false;
        }

        Stock -= notes;

        return true;
    }

    public bool Load(NoteCounts notes)
    {
        var after = Stock + notes;
        var fits = after.Fifties <= CassetteCapacity && after.Twenties <= CassetteCapacity && after.Tens <= CassetteCapacity;
        if (!IsValid(notes) || !fits)
        {
            return false;
        }

        Stock = after;

        return true;
    }

    private bool IsValid(NoteCounts notes) =>
        notes is { Fifties: >= 0, Twenties: >= 0, Tens: >= 0, Total: > 0 }
        && (Jammed is not { } cassette || notes.Of(cassette) == 0);
}
namespace Atm.Tests;

public sealed class CashMachineTests
{
    private static readonly NoteCounts Full = new(5, 5, 5);

    private static AtmResult Withdraw(int balance, int withdrawn, NoteCounts stock, Denomination? jammed, int amount,
        out MoneyDispenser dispenser)
    {
        dispenser = new MoneyDispenser(stock, jammed);

        return new CashMachine(dispenser).Execute(new AccountState(balance, withdrawn), new Operation.Withdraw(amount));
    }

    private static AtmResult Deposit(int balance, int withdrawn, NoteCounts stock, Denomination? jammed, NoteCounts notes,
        out MoneyDispenser dispenser)
    {
        dispenser = new MoneyDispenser(stock, jammed);

        return new CashMachine(dispenser).Execute(new AccountState(balance, withdrawn), new Operation.Deposit(notes));
    }

    private static void AssertRefused(AtmResult result, AtmStatus status, AccountState account)
    {
        Assert.Equal(status, result.Status);
        Assert.Equal(NoteCounts.None, result.Notes);
        Assert.Equal(0, result.Fee);
        Assert.Equal(account, result.Account);
    }

    // ---- Exemples de la spécification ----

    [Fact]
    public void Example_Withdraw60_UsesThreeTwenties()
    {
        var result = Withdraw(100, 0, new(1, 3, 0), null, 60, out var dispenser);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(0, 3, 0), 0, new(40, 60)), result);
        Assert.Equal(new NoteCounts(1, 0, 0), dispenser.Stock);
    }

    [Fact]
    public void Example_Withdraw80_UsesOneOfEach()
    {
        var result = Withdraw(100, 0, new(1, 1, 1), null, 80, out var dispenser);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(1, 1, 1), 0, new(20, 80)), result);
        Assert.Equal(NoteCounts.None, dispenser.Stock);
    }

    [Fact]
    public void Example_Withdraw100_NoFee()
    {
        var result = Withdraw(105, 0, Full, null, 100, out _);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(2, 0, 0), 0, new(5, 100)), result);
    }

    [Fact]
    public void Example_Withdraw110_ChargesFee()
    {
        var result = Withdraw(115, 0, Full, null, 110, out var dispenser);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(2, 0, 1), 5, new(0, 110)), result);
        Assert.Equal(new NoteCounts(3, 5, 4), dispenser.Stock);
    }

    [Fact]
    public void Example_Withdraw110_FeeMakesFundsInsufficient()
    {
        var result = Withdraw(110, 0, Full, null, 110, out var dispenser);

        AssertRefused(result, AtmStatus.InsufficientFunds, new(110, 0));
        Assert.Equal(Full, dispenser.Stock);
    }

    [Fact]
    public void Example_DailyLimitExceeded()
    {
        var result = Withdraw(250, 150, Full, null, 60, out var dispenser);

        AssertRefused(result, AtmStatus.DailyLimitExceeded, new(250, 150));
        Assert.Equal(Full, dispenser.Stock);
    }

    [Fact]
    public void Example_JammedCassetteCountsAsEmpty()
    {
        var result = Withdraw(250, 0, new(1, 0, 0), Denomination.Fifty, 50, out var dispenser);

        AssertRefused(result, AtmStatus.CannotDispense, new(250, 0));
        Assert.Equal(new NoteCounts(1, 0, 0), dispenser.Stock);
    }

    [Fact]
    public void Example_JammedFifty_UsesTwenties()
    {
        var result = Withdraw(250, 0, new(2, 2, 0), Denomination.Fifty, 40, out var dispenser);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(0, 2, 0), 0, new(210, 40)), result);
        Assert.Equal(new NoteCounts(2, 0, 0), dispenser.Stock);
    }

    [Fact]
    public void Example_Withdraw5_InvalidAmount()
    {
        var result = Withdraw(0, 200, NoteCounts.None, null, 5, out _);

        AssertRefused(result, AtmStatus.InvalidAmount, new(0, 200));
    }

    [Fact]
    public void Example_Deposit_CassetteFull()
    {
        var result = Deposit(10, 0, new(0, 5, 0), null, new(0, 1, 0), out var dispenser);

        AssertRefused(result, AtmStatus.CassetteFull, new(10, 0));
        Assert.Equal(new NoteCounts(0, 5, 0), dispenser.Stock);
    }

    [Fact]
    public void Example_Deposit_CassetteJammed()
    {
        var result = Deposit(10, 30, new(0, 1, 0), Denomination.Twenty, new(0, 1, 0), out var dispenser);

        AssertRefused(result, AtmStatus.CassetteJammed, new(10, 30));
        Assert.Equal(new NoteCounts(0, 1, 0), dispenser.Stock);
    }

    [Fact]
    public void Example_Deposit_Ok()
    {
        var result = Deposit(10, 30, new(1, 1, 0), null, new(1, 0, 1), out var dispenser);

        Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, new(70, 30)), result);
        Assert.Equal(new NoteCounts(2, 1, 1), dispenser.Stock);
    }

    // ---- Retrait : contrôles et ordre ----

    [Theory]
    [InlineData(-10)]
    [InlineData(0)]
    [InlineData(5)]
    [InlineData(15)]
    public void Withdraw_InvalidAmount(int amount)
    {
        var result = Withdraw(250, 0, Full, null, amount, out var dispenser);

        AssertRefused(result, AtmStatus.InvalidAmount, new(250, 0));
        Assert.Equal(Full, dispenser.Stock);
    }

    [Fact]
    public void Withdraw_InvalidAmount_CheckedBeforeDailyLimit()
    {
        var result = Withdraw(0, 200, NoteCounts.None, null, -10, out _);

        Assert.Equal(AtmStatus.InvalidAmount, result.Status);
    }

    [Fact]
    public void Withdraw_DailyLimit_CheckedBeforeFunds()
    {
        var result = Withdraw(0, 0, NoteCounts.None, null, 210, out _);

        Assert.Equal(AtmStatus.DailyLimitExceeded, result.Status);
    }

    [Fact]
    public void Withdraw_Funds_CheckedBeforeDispensability()
    {
        var result = Withdraw(10, 0, NoteCounts.None, null, 20, out _);

        Assert.Equal(AtmStatus.InsufficientFunds, result.Status);
    }

    [Fact]
    public void Withdraw_DailyLimitReachedExactly_IsAccepted()
    {
        var result = Withdraw(250, 150, Full, null, 50, out _);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(1, 0, 0), 0, new(200, 200)), result);
    }

    [Fact]
    public void Withdraw_FeeIsNotCountedInDailyLimit()
    {
        var result = Withdraw(250, 0, Full, null, 200, out _);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(4, 0, 0), 5, new(45, 200)), result);
    }

    [Fact]
    public void Withdraw_BalanceExactlyEnoughWithoutFee()
    {
        var result = Withdraw(100, 0, Full, null, 100, out _);

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(2, 0, 0), 0, new(0, 100)), result);
    }

    [Fact]
    public void Withdraw_NoExactCombination_CannotDispense()
    {
        var result = Withdraw(250, 0, new(1, 5, 0), null, 30, out var dispenser);

        AssertRefused(result, AtmStatus.CannotDispense, new(250, 0));
        Assert.Equal(new NoteCounts(1, 5, 0), dispenser.Stock);
    }

    [Fact]
    public void Withdraw_NotEnoughNotes_CannotDispense()
    {
        var result = Withdraw(250, 0, new(1, 1, 1), null, 90, out _);

        Assert.Equal(AtmStatus.CannotDispense, result.Status);
    }

    [Fact]
    public void Withdraw_FewestNotes_AvoidsGreedyTrap()
    {
        // 60 € sans billet de 10 : le glouton (50 d'abord) échoue, 20×3 réussit.
        var result = Withdraw(250, 0, new(5, 5, 0), null, 60, out _);

        Assert.Equal(new NoteCounts(0, 3, 0), result.Notes);
    }

    [Fact]
    public void Withdraw_FewestNotes_PrefersFiftyAndTen()
    {
        var result = Withdraw(250, 0, Full, null, 60, out _);

        Assert.Equal(new NoteCounts(1, 0, 1), result.Notes);
    }

    [Fact]
    public void Withdraw_JammedTen_UsesOtherNotes()
    {
        var result = Withdraw(250, 0, Full, Denomination.Ten, 90, out var dispenser);

        Assert.Equal(new NoteCounts(1, 2, 0), result.Notes);
        Assert.Equal(new NoteCounts(4, 3, 5), dispenser.Stock);
    }

    [Fact]
    public void Withdraw_JammedTwenty_UsesOtherNotes()
    {
        var result = Withdraw(250, 0, Full, Denomination.Twenty, 40, out var dispenser);

        Assert.Equal(new NoteCounts(0, 0, 4), result.Notes);
        Assert.Equal(new NoteCounts(5, 5, 1), dispenser.Stock);
    }

    [Fact]
    public void Withdraw_ManyNotes_SplitIntoPassesOfAtMostFour()
    {
        var dispenser = new FakeDispenser(Full);

        var result = new CashMachine(dispenser).Execute(new(250, 0), new Operation.Withdraw(200));

        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.All(dispenser.DispenseCalls, pass => Assert.InRange(pass.Total, 1, 4));
        Assert.Equal(new NoteCounts(4, 0, 0), result.Notes);
    }

    [Fact]
    public void Withdraw_NineNotes_UsesThreePasses()
    {
        // 140 € sans billet de 50 : 20×5 + 10×4 = 9 billets → 3 passages.
        var dispenser = new FakeDispenser(Full, Denomination.Fifty);

        var result = new CashMachine(dispenser).Execute(new(250, 0), new Operation.Withdraw(140));

        Assert.Equal(new AtmResult(AtmStatus.Ok, new(0, 5, 4), 5, new(105, 140)), result);
        Assert.Equal(3, dispenser.DispenseCalls.Count);
        Assert.All(dispenser.DispenseCalls, pass => Assert.InRange(pass.Total, 1, 4));
        Assert.Equal(new NoteCounts(0, 5, 4), dispenser.DispenseCalls.Aggregate(NoteCounts.None, (a, b) => a + b));
        Assert.Equal(new NoteCounts(5, 0, 1), dispenser.Stock);
    }

    // ---- Pannes ----

    [Fact]
    public void Withdraw_FaultOnFirstPass_NoNotes()
    {
        var dispenser = new FakeDispenser(Full) { FailDispenseAt = 1 };

        var result = new CashMachine(dispenser).Execute(new(250, 0), new Operation.Withdraw(60));

        AssertRefused(result, AtmStatus.DispenserFault, new(250, 0));
        Assert.Single(dispenser.DispenseCalls);
    }

    [Fact]
    public void Withdraw_FaultOnLaterPass_ReturnsNotesAlreadyDispensed()
    {
        var dispenser = new FakeDispenser(Full, Denomination.Fifty) { FailDispenseAt = 2 };

        var result = new CashMachine(dispenser).Execute(new(250, 0), new Operation.Withdraw(140));

        Assert.Equal(AtmStatus.DispenserFault, result.Status);
        Assert.Equal(dispenser.DispenseCalls[0], result.Notes);
        Assert.Equal(4, result.Notes.Total);
        Assert.Equal(0, result.Fee);
        Assert.Equal(new AccountState(250, 0), result.Account);
        Assert.Equal(2, dispenser.DispenseCalls.Count);
        Assert.Equal(Full - result.Notes, dispenser.Stock);
    }

    [Fact]
    public void Deposit_LoadFails_DispenserFault()
    {
        var dispenser = new FakeDispenser(NoteCounts.None) { FailLoad = true };

        var result = new CashMachine(dispenser).Execute(new(10, 30), new Operation.Deposit(new(1, 1, 1)));

        AssertRefused(result, AtmStatus.DispenserFault, new(10, 30));
        Assert.Single(dispenser.LoadCalls);
        Assert.Equal(NoteCounts.None, dispenser.Stock);
    }

    // ---- Dépôt ----

    [Fact]
    public void Deposit_Empty_InvalidAmount()
    {
        var result = Deposit(10, 0, NoteCounts.None, Denomination.Ten, NoteCounts.None, out _);

        AssertRefused(result, AtmStatus.InvalidAmount, new(10, 0));
    }

    [Fact]
    public void Deposit_Jammed_CheckedBeforeFull()
    {
        var result = Deposit(10, 0, new(5, 0, 0), Denomination.Fifty, new(1, 0, 0), out _);

        Assert.Equal(AtmStatus.CassetteJammed, result.Status);
    }

    [Fact]
    public void Deposit_OtherCassetteJammed_IsAccepted()
    {
        var result = Deposit(0, 0, new(0, 0, 4), Denomination.Fifty, new(0, 1, 1), out var dispenser);

        Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, new(30, 0)), result);
        Assert.Equal(new NoteCounts(0, 1, 5), dispenser.Stock);
    }

    [Fact]
    public void Deposit_FullTenCassette_RefusesEverything()
    {
        var result = Deposit(0, 0, new(0, 0, 5), null, new(1, 1, 1), out var dispenser);

        AssertRefused(result, AtmStatus.CassetteFull, new(0, 0));
        Assert.Equal(new NoteCounts(0, 0, 5), dispenser.Stock);
    }

    [Fact]
    public void Deposit_FullFiftyCassette()
    {
        var result = Deposit(0, 0, new(5, 0, 0), null, new(1, 0, 0), out _);

        Assert.Equal(AtmStatus.CassetteFull, result.Status);
    }

    // ---- Divers ----

    [Fact]
    public void Constructor_NullDispenser_Throws()
    {
        Assert.Throws<ArgumentNullException>(() => new CashMachine(null!));
    }

    [Fact]
    public void Execute_NullOperation_Throws()
    {
        var machine = new CashMachine(new MoneyDispenser(Full));

        Assert.Throws<ArgumentNullException>(() => machine.Execute(new(0, 0), null!));
    }

    private sealed record UnknownOperation : Operation;

    [Fact]
    public void Execute_UnknownOperation_Throws()
    {
        var machine = new CashMachine(new MoneyDispenser(Full));

        Assert.Throws<ArgumentException>(() => machine.Execute(new(0, 0), new UnknownOperation()));
    }
}
namespace Atm.Tests;

/// <summary>Compare la machine à un oracle écrit directement depuis la spécification, sur tout le domaine du stock.</summary>
public sealed class ExhaustiveTests
{
    private static readonly Denomination?[] JamStates = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];

    private static IEnumerable<NoteCounts> AllStocks()
    {
        for (var f = 0; f <= 5; f++)
            for (var t = 0; t <= 5; t++)
                for (var c = 0; c <= 5; c++)
                    yield return new NoteCounts(f, t, c);
    }

    private static IEnumerable<int> AllAmounts() =>
        new[] { -10, 0, 5 }.Concat(Enumerable.Range(1, 22).Select(i => i * 10));

    private static NoteCounts? Oracle(int amount, NoteCounts stock, Denomination? jammed)
    {
        var all = new List<NoteCounts>();
        for (var f = 0; f <= (jammed == Denomination.Fifty ? 0 : stock.Fifties); f++)
            for (var t = 0; t <= (jammed == Denomination.Twenty ? 0 : stock.Twenties); t++)
                for (var c = 0; c <= (jammed == Denomination.Ten ? 0 : stock.Tens); c++)
                {
                    var n = new NoteCounts(f, t, c);
                    if (n.Value == amount) all.Add(n);
                }

        if (all.Count == 0) return null;
        var min = all.Min(n => n.Total);
        var best = all.Where(n => n.Total == min).ToList();
        Assert.Single(best); // la spécification garantit l'unicité

        return best[0];
    }

    [Theory]
    [InlineData(250, 0)]
    [InlineData(250, 150)]
    [InlineData(120, 0)]
    [InlineData(105, 40)]
    [InlineData(0, 0)]
    public void Withdraw_MatchesOracle(int balance, int withdrawn)
    {
        foreach (var jammed in JamStates)
        foreach (var stock in AllStocks())
        foreach (var amount in AllAmounts())
        {
            var dispenser = new MoneyDispenser(stock, jammed);
            var account = new AccountState(balance, withdrawn);
            var result = new CashMachine(dispenser).Execute(account, new Operation.Withdraw(amount));

            var fee = amount > 100 ? 5 : 0;
            AtmStatus expected;
            NoteCounts? combination = null;
            if (amount <= 0 || amount % 10 != 0) expected = AtmStatus.InvalidAmount;
            else if (withdrawn + amount > 200) expected = AtmStatus.DailyLimitExceeded;
            else if (amount + fee > balance) expected = AtmStatus.InsufficientFunds;
            else if ((combination = Oracle(amount, stock, jammed)) is null) expected = AtmStatus.CannotDispense;
            else expected = AtmStatus.Ok;

            if (expected == AtmStatus.Ok)
            {
                var notes = combination!.Value;
                Assert.Equal(new AtmResult(AtmStatus.Ok, notes, fee, new(balance - amount - fee, withdrawn + amount)), result);
                Assert.Equal(stock - notes, dispenser.Stock);
            }
            else
            {
                Assert.Equal(new AtmResult(expected, NoteCounts.None, 0, account), result);
                Assert.Equal(stock, dispenser.Stock);
            }
        }
    }

    [Fact]
    public void Deposit_MatchesOracle()
    {
        foreach (var jammed in JamStates)
        foreach (var stock in AllStocks())
        for (var mask = 0; mask < 8; mask++)
        {
            var notes = new NoteCounts(mask & 1, (mask >> 1) & 1, (mask >> 2) & 1);
            var dispenser = new MoneyDispenser(stock, jammed);
            var account = new AccountState(100, 50);
            var result = new CashMachine(dispenser).Execute(account, new Operation.Deposit(notes));

            var after = stock + notes;
            AtmStatus expected =
                notes.Total == 0 ? AtmStatus.InvalidAmount
                : jammed is { } j && notes.Of(j) > 0 ? AtmStatus.CassetteJammed
                : after.Fifties > 5 || after.Twenties > 5 || after.Tens > 5 ? AtmStatus.CassetteFull
                : AtmStatus.Ok;

            if (expected == AtmStatus.Ok)
            {
                Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, new(100 + notes.Value, 50)), result);
                Assert.Equal(after, dispenser.Stock);
            }
            else
            {
                Assert.Equal(new AtmResult(expected, NoteCounts.None, 0, account), result);
                Assert.Equal(stock, dispenser.Stock);
            }
        }
    }
}
namespace Atm.Tests;

/// <summary>Module de billets simulé : délègue au vrai module, mais peut tomber en panne sur demande.</summary>
internal sealed class FakeDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    private readonly MoneyDispenser _inner = new(stock, jammed);

    /// <summary>Numéro (à partir de 1) de l'appel à <see cref="Dispense"/> qui échoue, ou <c>null</c>.</summary>
    public int? FailDispenseAt { get; init; }

    public bool FailLoad { get; init; }

    public List<NoteCounts> DispenseCalls { get; } = [];

    public List<NoteCounts> LoadCalls { get; } = [];

    public NoteCounts Stock => _inner.Stock;

    public Denomination? Jammed => _inner.Jammed;

    public bool Dispense(NoteCounts notes)
    {
        DispenseCalls.Add(notes);

        return DispenseCalls.Count != FailDispenseAt && _inner.Dispense(notes);
    }

    public bool Load(NoteCounts notes)
    {
        LoadCalls.Add(notes);

        return !FailLoad && _inner.Load(notes);
    }
}
